function output=d2_phi1(x,d0,d1,d2,d3)
q=1/30;
output=-exp(-(x - d0/2 - d1/2)^2/(2*q^2*(d1 - d0)^2))*(((x - d1/2 - d2/2)/(2*q^2*(d2 - d1)^2) + (x - d1/2 - d2/2)^2/(q^2*(d2 - d1)^3))*exp(-(x - d1/2 - d2/2)^2/(2*q^2*(d2 - d1)^2)) + ((x - d2/2 - d3/2)/(2*q^2*(d3 - d2)^2) - (x - d2/2 - d3/2)^2/(q^2*(d3 - d2)^3))*exp(-(x - d2/2 - d3/2)^2/(2*q^2*(d3 - d2)^2)))/(exp(-(x - d0/2 - d1/2)^2/(2*q^2*(d1 - d0)^2)) + exp(-(x - d1/2 - d2/2)^2/(2*q^2*(d2 - d1)^2)) + exp(-(x - d2/2 - d3/2)^2/(2*q^2*(d3 - d2)^2)))^2;
end